// iconButton is a button showing only an icon, named for screen readers.
func iconButton(c *ui.Context, icon *ui.SVG, label string) ui.Element {
	return ui.Button(c, "").Label(label).Tooltip(label).Children(func() { ui.Icon(c, icon) })
}
